#!/usr/bin/env python3
"""Qualify unknown inactive payloads against independently concretized source RTL."""
import argparse,hashlib,json,shutil,subprocess
from pathlib import Path
R=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser(__doc__);p.add_argument('--bridge',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();bridge=a.bridge.resolve();out=a.output.resolve();out.mkdir(parents=True,exist_ok=False);source=R/'timing/saturn_timing_live_bridge_inactive.cpp';shutil.copy2(source,out/source.name);shutil.copy2(Path(__file__),out/'runner.py');patterns=R/'build/saturn-timing-live-bridge-fixture-v4/ownership_instruction_patterns.hpp';shutil.copy2(patterns,out/patterns.name);cmd=['/usr/bin/g++','-O3','-std=c++20','-pthread','-I'+str(out),'-I'+str(bridge/'sdk'),str(out/source.name),str(bridge/'sdk/libiris_saturn_live_bridge.a'),'-latomic','-lz','-o',str(out/'inactive')]
 with(out/'build.log').open('w')as log:subprocess.run(cmd,stdout=log,stderr=subprocess.STDOUT,check=True)
 rows=[]
 for seed in[0,17,91]:
  q=subprocess.run([str(out/'inactive'),str(seed)],capture_output=True,text=True,timeout=60);(out/f'seed{seed}.stdout').write_text(q.stdout);(out/f'seed{seed}.stderr').write_text(q.stderr);rows.append({'seed':seed,'exit_status':q.returncode,'result':json.loads(q.stdout.splitlines()[-1])if q.returncode==0 else None})
 source_dir=R/'build/saturn-timing-component-v1-final/build/saturn-timing-source-v1';sources=[source_dir/'compute/rtl/PipelinedFaultCheck.sv',source_dir/'compute/rtl/SaturnShuttleFrontend.sv',source_dir/'rocket/rtl/PipelinedFaultCheck_2.sv',source_dir/'rocket/rtl/SaturnRocketFrontend.sv',R/'build/rtl-verilator/gen-collateral/EarlyVectorDecode.sv',R/'build/rtl-verilator/gen-collateral/EarlyVectorDecode_4.sv'];sources=[s for s in sources if s.is_file()]
 contract={'policy':'SourceQualifiedInactivePayload (explicit opt-in; default remains AllInputsDefined)','EX_payload':'Only ex_valid=0 may have unknown PC/raw/vconfig/vstart/operand payload; source PFC latches on S0valid only. ActivePC/raw/config/vstart staystrict.','unused_XPRs':'Saved EarlyVectorDecode: arithmetic read_rs1 only funct3 4/6; arithmetic never read_rs2. Their unused scalar transports may be concretized without initializing architectural registers.','MEM_FRS1':'Only allowed if every admitted exact32bit encoding has funct3 neither1nor5; saved PFC S1override uses FRS1 onlyfor those float classes. Masked capabilities cannot claim this rule.','late_rounding':'Unknown FRM/VXRM allowed only reset or actual PFC.S2valid=0 and IFC.busy=0. The late-consumption condition is checked after evaluate; failure poisons without a source edge.','concretization':'Clear unknown input bits only for an unconsumed source payload; retain original known_bits. No architectural initialization, observed-state input, queue/readiness injection or future value publication.','live_commands':'Unique per-reset-epoch/command-sequence references across source front/VAT/sequencers/pipes/FP8/readout/VRFLL/scalar/VMU/TL/FPU lifetimes; union with CPU unretired/speculative references and apply events before releasing final references.','bounded_test':'Direct source unit receives independently randomized inactive/unused payload values; compare all qualified physical control, accepted ownership and numeric write events against the bridge concretization, then execute real vmv/vadd/scalarreadback. This is an explicit synthetic external EX fixture, not actual CPU/ELF or four-state proof.','source_sha256':{str(s):sha(s)for s in sources}};(out/'input-knownness-contract.json').write_text(json.dumps(contract,indent=2)+'\n')
 inputs=[Path(__file__),source,patterns,bridge/'build.json',bridge/'sdk/libiris_saturn_live_bridge.a',*sources,Path('/usr/bin/g++')];report={'schema':'iris.saturn_live_bridge_inactive_payload_proof.v1','pass':all(r['exit_status']==0 for r in rows),'argv':cmd,'runs':rows,'input_sha256':{str(p):sha(p)for p in inputs},'binary_sha256':sha(out/'inactive'),'contract_sha256':sha(out/'input-knownness-contract.json'),'RTL_state_injected':False,'architectural_knownness_inferred':False,'actual_CPU_ELF_execution':False,'hardware_contacted':False};(out/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'pass':report['pass'],'report_sha256':sha(out/'report.json'),'runs':rows}))
 if not report['pass']:raise SystemExit(1)
if __name__=='__main__':main()
